#!/usr/bin/env python3
"""Patch 101: Final check export for an AI to verify (one markdown file, or one file per source). Careerflow platform enhancements. Run from the repo root (the folder that holds backend/ and frontend/).
Safe to run twice: files already applied are skipped."""
import os, sys, zlib, base64
sys.stdout.reconfigure(errors='replace')
NEW = {'backend/app/services/llm_pack.py': ''}
MOD = {'backend/app/api/v1/routes/quality.py': [('        for i, j in pairs:\n            r, fr = recs[j], final_recs[i]\n            label = ak.record_name(r.extracted_fields or {}, r.canonical_name) or f"record {j + 1}"\n            rows = ak.compare(r.extracted_fields or {}, fr, ignore_set)\n', '        if export in ("llm", "llm_zip"):      # extra context for the pack a language model verifies from\n            sd["website_url"] = s.website_url\n            sd["sop"] = {"required": sorted(req.get("required") or []) if sop_on else [], "allowed": sorted(req.get("allowed") or []) if (sop_on and req.get("allowed")) else []}\n            sd["pack"] = []\n        for i, j in pairs:\n            r, fr = recs[j], final_recs[i]\n            label = ak.record_name(r.extracted_fields or {}, r.canonical_name) or f"record {j + 1}"\n            rows = ak.compare(r.extracted_fields or {}, fr, ignore_set)\n            if export in ("llm", "llm_zip"):\n                sd["pack"].append({"record": label, "extractor": r.extracted_fields or {}, "final": fr,\n                                   "comments": {f_: [{"comment": e.get("comment"), "type": e.get("type"), "role": e.get("role")} for e in (lst or []) if isinstance(e, dict)][:4]\n                                                for f_, lst in (r.reviewer_field_comments or {}).items() if isinstance(lst, list)}})\n'), ('    if export in ("xlsx", "json"):\n        from fastapi.responses import Response\n        from app.services import quality_export as qx\n', '    if export in ("llm", "llm_zip"):\n        from fastapi.responses import Response\n        from app.services import llm_pack as lp\n        stamp = enh.now_utc().strftime("%Y%m%d")\n        if export == "llm":\n            return Response(content=lp.combined_md(result, {"generated": stamp}).encode("utf-8"), media_type="text/markdown; charset=utf-8",\n                            headers={"Content-Disposition": f\'attachment; filename="final_check_for_llm_{stamp}.md"\'})\n        return Response(content=lp.zip_pack(result, {"generated": stamp}), media_type="application/zip",\n                        headers={"Content-Disposition": f\'attachment; filename="final_check_for_llm_{stamp}.zip"\'})\n    if export in ("xlsx", "json"):\n        from fastapi.responses import Response\n        from app.services import quality_export as qx\n')], 'frontend/src/api/client.ts': [("answerKeyDownload: async (file: File, o: { format: 'xlsx' | 'json';", "answerKeyDownload: async (file: File, o: { format: 'xlsx' | 'json' | 'llm' | 'llm_zip';"), ("a.download = `final_check_${new Date().toISOString().slice(0, 10).replace(/-/g, '')}.${o.format}`", "a.download = `final_check${o.format.startsWith('llm') ? '_for_llm' : ''}_${new Date().toISOString().slice(0, 10).replace(/-/g, '')}.${o.format === 'llm' ? 'md' : o.format === 'llm_zip' ? 'zip' : o.format}`")], 'frontend/src/components/enh/FinalCheck.tsx': [("const download = async (format: 'xlsx' | 'json') => {", "const download = async (format: 'xlsx' | 'json' | 'llm' | 'llm_zip') => {"), ('          {res && <Button variant="secondary" onClick={() => download(\'json\')} disabled={!!busy}>JSON</Button>}', '          {res && <Button variant="secondary" onClick={() => download(\'json\')} disabled={!!busy}>JSON</Button>}\n          {res && <Button variant="secondary" onClick={() => download(\'llm\')} disabled={!!busy} title="One markdown file with the task, every item to verify, the reviewers\' comments, the SOP rules and the full records on both sides. Give it to an AI to check against the sources.">{busy === \'download\' ? \'Preparing…\' : \'For an AI\'}</Button>}\n          {res && <Button variant="secondary" onClick={() => download(\'llm_zip\')} disabled={!!busy} title="The same, as one file per source plus the task, for when the single file is too long for the AI to take">For an AI (split)</Button>}')]}
root = os.getcwd()
if not (os.path.isdir(os.path.join(root, 'backend')) and os.path.isdir(os.path.join(root, 'frontend'))):
    sys.exit('Run this from the repo root (the folder containing backend and frontend).')
def rd(p): return open(p, encoding='utf-8', newline='').read()
done = skipped = 0; bad = []
for rel, hunks in MOD.items():
    p = os.path.join(root, rel)
    if not os.path.exists(p): bad.append(rel + ' (missing)'); continue
    raw = rd(p); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n'); changed = False
    for old, new in hunks:
        if new in t and not (new in old and new != old): continue
        elif t.count(old) == 1: t = t.replace(old, new); changed = True
        elif new in t: continue
        else: bad.append(rel + ' (a section does not match; file differs from expected version)'); break
    else:
        if changed:
            open(p, 'w', encoding='utf-8', newline='').write(t.replace('\n', '\r\n') if crlf else t); done += 1; print('updated ', rel)
        else: skipped += 1
for rel, blob in NEW.items():
    p = os.path.join(root, rel); data = zlib.decompress(base64.b64decode(blob))
    if os.path.exists(p) and open(p, 'rb').read() == data: skipped += 1; continue
    os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(data); done += 1; print('wrote   ', rel)
print(f'\n{done} changed, {skipped} already applied.')
if bad:
    print('\nPROBLEMS:'); [print(' -', b) for b in bad]; sys.exit(1)
